css:
:root{--text-lg:20px;--ink:#243734;--paper:#fbfcf8;--muted:#637571;--accent:#b45428}
*{box-sizing:border-box}
.card{margin:0;padding:20px;background:var(--paper);color:var(--ink);font:var(--text-lg)/1.7 system-ui,"Microsoft YaHei",sans-serif;text-align:left}
.nightMode{--ink:#e1e9e3;--paper:#202b28;--muted:#b7c9bf;--accent:#f5b58c}
.CardSide{max-width:760px;margin:auto;overflow-wrap:anywhere}
.Top,.CheckNote{color:var(--muted);font-size:14px}
.VocabKanji{font-size:36px;text-align:center;margin:18px 0}
.VocabFurigana{text-align:center;margin:22px 0;font-size:26px}
.VocabPoS{font:inherit}.PosLabel,.VocabDef{font:inherit}.PosLabel{margin-right:.5em}
.SentenceList{list-style:none;margin:20px 0;padding:0}
.Sentence{padding:16px 0;border-top:1px solid var(--muted)}
.SentKanji{font:inherit;margin:0}.SentDef{font:inherit;color:var(--muted);margin:8px 0}
em{font-style:normal;margin-right:.5em}
.PitchReading{display:inline-flex;white-space:nowrap;margin:.3em .5em;line-height:1.4}
.PitchReading small{font-size:.6em;margin-left:.4em;color:var(--accent)}
.PitchMora{position:relative;display:inline-block}
.PitchMora:before{content:"";position:absolute;left:0;right:0;border-top:2px solid var(--accent)}
.PitchHigh:before{top:-.25em}.PitchLow:before{top:0}
.PitchChange:after{content:"";position:absolute;left:0;top:-.25em;height:.25em;border-left:2px solid var(--accent)}
.PitchTail:before{border-right:2px solid var(--accent);height:.25em}
@media(max-width:480px){.card{padding:12px}.VocabKanji{font-size:30px}.VocabFurigana{font-size:23px}}
